p='packages/std-avrac/src/core/rebuild.av'
s=open(p).read()
a="""    mut fn scoped_name(text: Scoped) -> Scoped {
        if !self.verbatim && hole_name(text.text()) != null && !self.holed.is_empty() { self.holed.set(self.holed.length - 1, true) }
        let named = self.rewritten(text.text())
        let mark? = self.fresh else { return scoped(named) }
        if self.copying &&
            !self.verbatim &&
            hole_name(text.text()) == null &&
            self.binds.contains(text.text()) { return scoped("${named}${mark}") }
        scoped(named)
    }"""
assert a in s
s=s.replace(a,"""    mut fn scoped_name(name: Scoped) -> Scoped {
        let text = name.text()
        let holed = hole_name(text) != null
        if !self.verbatim && holed && !self.holed.is_empty() { self.holed.set(self.holed.length - 1, true) }
        let named = self.rewritten(text)
        if self.fresh != null && self.copying && !self.verbatim && !holed && self.binds.contains(text) {
            return scoped("${named}${self.fresh!}")
        }
        // A name no rewrite reached is the name it was: it is handed on, not minted again.
        if named == text { name } else { scoped(named) }
    }""")
open(p,'w').write(s)
