/// A mark folded into a node's print: its code, and what it carries as one value.
export type Stamp = { code: int, value: int }

fn no_prints() -> Stamped {
    Stamped {
        identities: list_cell(),
        stamps: list_cell(),
        prints: list_cell(),
        settled_in: list_cell(),
        pass: Cell.new(0),
        passes: Cell.new(0),
        settled: Cell.new(0),
        stale: Cell.new(false),
    }
}

fn no_stamps() -> List<Stamp>? { null }

impl Stamped {
    /// A node added, printed as what it is.
    fn added(identity: int) {
        self.identities.push(identity)
        self.stamps.push(no_stamps())
        self.prints.push(identity)
        self.settled_in.push(0)
    }

    /// Node `at` wears the mark `code`, carrying `value`.
    fn stamp(at: int, code: int, value: int) {
        let kept = [s for s in self.stamps.get()[at] ?? [] if s.code != code]
        let stamps = [s for s in kept if s.code < code]
            .concat([Stamp { code: code, value: value }])
            .concat([s for s in kept if s.code > code])
        self.stamps.set_at(at, stamps)
        self.refold(at)
        self.written(at)
    }

    /// Node `at` was written: outside a settle, one a settle derived makes every print stale.
    fn written(at: int) { if self.pass.get() == 0 && at < self.settled.get() { self.stale.set(true) } }

    /// Whether a node a settle derived was written since, outside a settle.
    fn stale_since() -> bool { self.stale.get() }

    fn refold(at: int) {
        let identity = self.identities.get()[at]
        let stamps? = self.stamps.get()[at] else {
            self.prints.set_at(at, identity)
            return
        }
        self.prints.set_at(at, stamps.fold(identity, (acc, s) -> fp(s.code, [acc, s.value])))
    }

    fn print(at: int) -> int { self.prints.get()[at] }

    fn begun() {
        self.passes.set(self.passes.get() + 1)
        self.pass.set(self.passes.get())
    }

    /// The settle under way ends, having derived every node up to `count`.
    fn ended(count: int) {
        self.pass.set(0)
        self.settled.set(count)
        self.stale.set(false)
    }

    /// The first node no settle has derived.
    fn unsettled_from() -> int { self.settled.get() }

    /// Whether a settle is under way and hasn't derived node `at`'s print yet.
    fn unsettled(at: int) -> bool { self.pass.get() > 0 && self.settled_in.get()[at] != self.pass.get() }

    /// Node `at` is being derived in this settle; asked again inside it, it answers what it held.
    fn settling(at: int) { self.settled_in.set_at(at, self.pass.get()) }

    /// The prints as they stand, in tables of their own.
    fn forked() -> Stamped {
        Stamped {
            identities: Cell.new(self.identities.get()),
            stamps: Cell.new(self.stamps.get()),
            prints: Cell.new(self.prints.get()),
            settled_in: Cell.new(self.settled_in.get()),
            pass: Cell.new(self.pass.get()),
            passes: Cell.new(self.passes.get()),
            settled: Cell.new(self.settled.get()),
            stale: Cell.new(self.stale.get()),
        }
    }

    /// Node `at` is what `identity` says, wearing the stamps it wore.
    fn reidentified(at: int, identity: int) {
        self.identities.set_at(at, identity)
        self.refold(at)
    }
}

fn no_stmt_marks() -> StmtMarks {
    StmtMarks {
        is_exported: false,
