fn same_text(a: string, b: string) -> bool { a == b }

/// The name the text numbered `number` of a tape of `count` texts spells, `text`, interned once a
/// tape: `ids` holds, by each text's number, the id it was minted, -1 for one not read as a name
/// yet, and nothing before any text is.
export fn tape_name(ids: Cell<List<int>>, count: int, number: int, text: string) -> Name {
    let known = id_read(ids, number)
    if known >= 0 { return Name { id: known } }
    if known == NONE_READ { ids.set([0 - 1 for _text in 0..count]) }
    let minted = name_of(text)
    ids.set_at(number, minted.id)
    minted
}

/// What `ids` holds for the text numbered `number`, read and let go before it is written.
fn id_read(ids: Cell<List<int>>, number: int) -> int {
