    all_defs: List<Def>,
    def_names: List<string>,
    visible: Map<string, Binding>,
    overlays: List<Map<string, Binding>>,
    // the open lambda frames; the open fn bodies' floors; one entry
    // per open impl or trait body (inside, `self` names the receiver
    // seat and the written params start at seat 1); the open fn
    // body's seat contracts, by written position
    lframes: List<LFrame>,
    floors: List<int>,
    receivers: List<SelfSeat>,
    marks: List<List<SeatMark>>,
    // a name resolves ONCE; a scoped binder never counts as a later
    // definition
    walked: SideTable<bool>,
    scoped: SideTable<bool>,
    // THE WALK'S STATE: the open fn body's seat names, and whether
    // the statement in hand stands inside a block
    scope: List<string>,
    in_block: bool,
    // the type parameters the open declarations name, and each read of
    // one no static call has seated yet
    tnames: List<string>,
    unseated: List<ExprId>,
    // the two looks past the written file
    elsewhere: Elsewhere,
}

/// The resolver's two looks PAST the written file. A name the
/// written namespace lacks may be a GENERATED declaration of this
/// file, materialized on demand (the two-tier lookup's second tier);
/// and a template's own name lives in the namespace of the file that
/// WROTE the quote — origin hygiene.
export type Elsewhere = {
    generated: fn(string) -> DeclId?,
    written_in: fn(FileId) -> Namespace,
    // the parse error the file's module is unread behind, asked only when
    // a refusal is being worded — a clean check reads no sibling for it
    unread: fn() -> Diag?,
}

impl Elsewhere {
    fn unread_root() -> Diag? {
