    /// so its bodies see the target's own.
    fn tparams_in_scope(s: StmtId) -> List<string> {
        let written = self.view.store.tparams_in_scope(s)
        if !written.is_empty() { return written }
        let target? = self.view.store.impl_parts(s)?.target else { return [] }
        let d? = self.facts.names.type_decl(target) else { return [] }
        self.view.decls.tparams(d)
    }

    /// The scope back where it stood; a read of a type parameter that
    /// no static call seated is refused as it leaves, and binds nothing
    /// — so no later pass speaks about it again.
    mut fn close_tparams(at: int) {
        if self.tnames.length == at { return }
        self.tnames = self.tnames.slice(0, at)
        for e in self.unseated {
            self.emit(type_param_value(self.loc_of(e), self.view.store.ident_name(e) ?? ""))
            self.facts.bindings.set(e.index, null)
        }
        self.unseated = []
    }

    /// A type parameter read as the subject of a call: seated, so its
    /// read stands.
    mut fn seat_type_read(e: ExprId) {
        self.unseated = [u for u in self.unseated if !same_expr(u, e)]
    }

    /// A statement list under its own overlay scope — a loop body.
    mut fn scope_stmts(stmts: List<StmtId>) {
        self.open_overlay()
        self.resolve_stmts(true, stmts)
        self.close_overlay()
    }

    /// A fresh scope where `s`'s own binding holds: the exprs walk
    /// and the statements resolve inside it, and the binding dies at
    /// exit — a loop variable's home. A scoped binder never counts
    /// as a later definition: its name outside the scope is plainly
    /// unknown.
    mut fn bound_scope(s: StmtId, exprs: List<ExprId>, stmts: List<StmtId>) {
        self.scoped.set(s.index, true)
        self.open_overlay()
        self.bound_body(s, exprs, stmts)
        self.close_overlay()
    }

    /// Inside the bound scope: the binder holds, the exprs walk, the
    /// statements resolve.
    mut fn bound_body(s: StmtId, exprs: List<ExprId>, stmts: List<StmtId>) {
        self.bind_checked(s)
        self.bind_index(s)
        for e in exprs { self.walk(e) }
        self.resolve_stmts(true, stmts)
    }

    /// A block's statements under a fresh overlay scope: binds are
    /// visible onward and restored at exit.
    mut fn block_scope(stmts: List<StmtId>, value: ExprId?) {
        self.open_overlay()
        self.block_body(stmts, value)
        self.close_overlay()
    }

    /// Inside a block's scope: the statements, then the value —
    /// absent when the block leaves instead of answering.
    mut fn block_body(stmts: List<StmtId>, value: ExprId?) {
        self.resolve_stmts(true, stmts)
        if value != null { self.walk(value!) }
    }

    /// One match arm's scope: its binds (in pattern order) hold for
    /// the arm's guard AND value, and die with both — the first scope
    /// in the language opened by an EXPRESSION rather than a
    /// statement. An unguarded arm writes no guard.
    mut fn arm_scope(binds: List<Bound>, value: ExprId, guard: ExprId? = null) {
        self.open_overlay()
        self.arm_body(binds, value, guard)
        self.close_overlay()
    }

    mut fn arm_body(binds: List<Bound>, value: ExprId, guard: ExprId?) {
        for j, b in binds {
            if !self.refused_binder(b.name, self.loc_of(value), b.origin) { self.bind(keyed(b.name, b.origin), Binding.Pattern(value, j)) }
        }
        if guard != null { self.walk(guard!) }
        self.walk(value)
    }

    /// Binders NAMED ON a node — a comprehension's, a catch's, a
    /// nullable match's — wear the node's origin.
    fn bound_at(e: ExprId, names: List<string>) -> List<Bound> {
        let origin: FileId? = self.view.origin_of(e)
        [Bound { name: n, origin: origin } for n in names]
    }

    /// A pattern's binders, each wearing the origin of its own text.
    fn bound_pats(binders: List<Binder>) -> List<Bound> {
        [Bound { name: b.name, origin: self.view.origin_of_pat(b.pat) } for b in binders]
    }

    /// A lambda's body under its own frame: params bind, outer names
    /// capture, and the frame dies with the walk. A plain param keys by
    /// the lambda's origin, or the body's when a sibling param named through
    /// a hole made the lambda itself holed: the plain ones stay the template's.
    mut fn lambda_scope(lam: ExprId, params: List<Param>, body: ExprId) {
        // a refused param name still BINDS (declare the wreckage) — the
        // body resolves quietly and the one refusal stands alone
        for pp in params {
            let _ = self.refused_binder(pp.name.text(), self.loc_of(lam), self.view.origin_of(lam))
        }
        let origin: FileId? = self.view.origin_of(lam) ?? self.view.origin_of(body)
        // LICENSED compiler.bracket_ritual: this IS the bracket
        self
            .lframes
            .push(
                LFrame {
                    lam: lam,
                    params: [self.seat_key(pp, origin) for pp in params],
                    floor: self.overlays.length,
                },
            )
        self.walk(body)
        let _ = self.lframes.pop()
    }

    /// One subtree's resolution, children before owners.
    /// An annotation's callee and arguments resolve as expressions do.
    mut fn walk_annotation(a: Annotation) {
        self.walk(a.callee)
        for e in a.args { self.walk(e) }
    }

    mut fn walk(root: ExprId) {
        for e in post_order(self.dispatch, self.view.store, root) { self.view.store.expr(e).resolve(self, e) }
    }

    /// An impl's or a trait's fns: `self` names a receiver for
    /// exactly their resolution — member by member, because a
    /// `static fn` among them has none.
    mut fn impl_stmts(body: List<StmtId>) {
        for s in body { self.impl_member(s) }
    }

    /// One member. A `static fn` resolves with NO receiver, so
    /// `self` inside it refuses and its seats start at 0.
    mut fn impl_member(s: StmtId) {
        self
            .receivers
            .push(if self.view.store.is_static(s) { SelfSeat.Static } else { SelfSeat.Receiver })
        self.resolve_stmts(false, [s])
        let _ = self.receivers.pop()
