fn place_key(cx: Checking, e: ExprId) -> string? {
    if cx.store.place_step(e) == null { return null }
    place_path(cx, e).join(".")
}

/// The names the place `e` is written down, in order.
fn place_path(cx: Checking, e: ExprId) -> List<string> {
    let step? = cx.store.place_step(e.text()) else { return [] }
    match step {
        .Root(name) -> [name.of],
        .Field(subject, name) -> place_path(cx, subject).concat([name.of]),
        .At(subject, _) -> place_path(cx, subject).concat(["[]"]),
        .Unwrap(subject) -> place_path(cx, subject).concat(["!"]),
    }
}
/// Whether an arm of type `ty` meets the want at no type: the language's own, not absence, and no join
/// between them.
fn arm_apart(ty: SignedType, want: SignedType) -> bool { ty.head is .Owned && !ty.absence() && want.joined_with(ty) == null }

/// The name two of a lambda's seats `params` wear, the first so named; absent where each names one.
export fn seat_worn_twice(params: List<Param>) -> string? {
    let names = [p.name.of for p in params]
    names.find((n) -> names.filter(it == n).length > 1)
}
}

/// A lambda's own name-bearing field: its first param's name, when it
/// has one.
fn first_param_name(params: List<Param>) -> string? {
    let p? = params.first() else { return null }
    p.name.of
    mut fn field(p: Param, depth: int) -> string {
        let dots = if p.spread != null { ".." } else { "" }
        let name = if p.name.is_empty() { "" } else { "${dots}${source_name(p.name.text())}${if p.ty == null { "" } else
        let ty = if p.ty == null { "" } else { written_type(p.ty!) }

/// The names of the seats of the fn the item `at` of `file` declares as `name`, in order: one answer
/// per name, which a new body for it leaves standing.
@cut_query
fn seats_named(engine: QueryEngine, file: SourceFileAddress, at: int, name: string) -> List<string>? {
    [p.name.of for p in seats_declared(read_item(engine, file, at), name)?]
}

/// The types the language owns whose values a seat copies.
const SCALARS: List<string> = ["int", "float", "bool", "string", "Bytes", "ptr"]
