t=t[:i]+'''/// Every terminal item slotted — a class by its place in `terms`, a literal by its place in
/// `lit_slots` — and every labelled item by its label's place in `labels`, groups opened.
fn slotted(g: Grammar, terms: List<string>, lit_slots: Map<string, int>, labels: Map<string, int>) -> Grammar {
    g with { rules: [r with { body: slotted_alt(r.body, terms, lit_slots, labels) } for r in g.rules] }
}

fn slotted_alt(a: Alt, terms: List<string>, lit_slots: Map<string, int>, labels: Map<string, int>) -> Alt {
    a with { branches: [s with { items: [slotted_item(m, terms, lit_slots, labels) for m in s.items] } for s in a.branches] }
}

fn slotted_item(m: Item, terms: List<string>, lit_slots: Map<string, int>, labels: Map<string, int>) -> Item {
    let labelled = m with { label_slot: if m.label == null { 0 - 1 } else { labels.get(m.label!) ?? 0 - 1 } }
    match m.prim {
        .Named(term) -> labelled with { slot: terms.index_of(term) },
        .Lit(text) -> labelled with { slot: lit_slots.get(text) ?? 0 - 1 },
        .Group(inner) -> labelled with { prim: Prim.Group(slotted_alt(inner, terms, lit_slots, labels)) },
        .Ref(_) or .NotChar(_) -> labelled,
    }
}

/// The labels a pair's build reads, at their places in `Ready.labels`.
const PAIR_LEFT: int = 0
const PAIR_OP: int = 1
const PAIR_RIGHT: int = 2
const PAIR_LABELS: List<string> = ["left", "op", "right"]

/// Every label the branches of `a` bind, a fold's seed among them, groups opened, in order.
fn labels_of(a: Alt) -> List<string> {
    flatten([some_list(s.fold).concat(flatten([some_list(m.label).concat(group_labels(m.prim)) for m in s.items])) for s in a.branches])
}

/// The labels inside the group the prim `p` opens; none for any other prim.
fn group_labels(p: Prim) -> List<string> {
    match p {
        .Group(inner) -> labels_of(inner),
        .Ref(_) or .Named(_) or .Lit(_) or .NotChar(_) -> [],
    }
}

