#!/usr/bin/env python3
"""Where the old path and the program layer differ over the sources std-avrac's specs ask.

`AVRA_SPEC_DIFFERENTIAL=1 build/avra test packages/std-avrac/<dir> > log` prints one block per
source whose diagnostics or run differ. This reads those logs and says, over the DISTINCT sources:
each kind the old path says and the layer doesn't, each the layer says and the old path doesn't,
each kind both say in different words, each reason the layer gives for not making a program the
old path runs, and each program the two run to different answers.

    python3 tools/spec_differential.py LOG... [--examples N] [--json FILE]
"""
import collections
import json
import re
import sys

BLOCK = re.compile(
    r"=====DIFF\n--SRC\n(.*?)\n--OLDK\n(.*?)\n--NEWK\n(.*?)\n--OLDRUN\n(.*?)\n--NEWRUN\n(.*?)\n=====END",
    re.S,
)
NOT_MADE = re.compile(r"ERR:not made on the program layer: (.*?), at ")


def kinds(said):
    return collections.Counter(line.split(":")[0] for line in said.split("\n") if line)


def blocks(paths):
    """Each differing source once: (source, old said, new said, old run, new run)."""
    seen = {}
    for path in paths:
        with open(path, errors="replace") as log:
            for block in BLOCK.findall(log.read()):
                seen.setdefault(block[0], block)
    return list(seen.values())


def tallied(found):
    missing, extra, worded, unmade = (collections.defaultdict(list) for _ in range(4))
    ran_apart = []
    for src, old, new, old_run, new_run in found:
        was, now = kinds(old), kinds(new)
        for kind in was - now:
            missing[kind].append(src)
        for kind in now - was:
            extra[kind].append(src)
        if was != now:
            continue
        if old != new:
            for kind in was:
                worded[kind].append(src)
            continue
        reason = NOT_MADE.match(new_run)
        if reason:
            unmade[re.sub(r"`[^`]*`", "`…`", reason.group(1))].append(src)
        elif old_run != new_run:
            ran_apart.append((src, old_run, new_run))
    return missing, extra, worded, unmade, ran_apart



/// EVERYTHING A PROGRAM SAID — what its manifests and its package graph say, then each refusal
/// and warning of its files. A suite over an in-memory package asks a `Judged`, not a source.
export fn said(p: Judged) -> List<Diag> { p.diagnostics }

/// `refused_with` for a program already judged: the words, and the
/// COUNT, so no cascade hides behind the phrase the case names.
export fn refused_n(p: Judged, phrase: string, n: int) -> bool {
    p.diagnostics.length == n && p.report().contains(phrase)
}

/// One mistake, one message — the count a refusal test pins by
/// default.
export fn refused_in(p: Judged, phrase: string) -> bool {
    refused_n(p, phrase, 1)
}

/// The program as IR, memory strategy applied.
export fn ir_of(source: string) -> Lowered {
    if !ir_differential() { return lowered_alone(source) }
    let was = [unnamed(line) for line in render_ir(analyze_source(source).lowered()).split("\n")]
    one_shot_let_go()
    let j = held_alone(source).judged(entry_of("alone"))
    ir_differ(source, was, j)
    j.lowered()
}

/// One source's IR on the program layer, the program never run: a source a spec lowers may be
/// one that never ends.
fn lowered_alone(source: string) -> Lowered { held_alone(source).judged(entry_of("alone")).lowered() }

    ]
}

/// A program at `/w` with `@std/meta` and a provider package `@x/c`
/// whose one file is `provider`, which sees `Code` — the shape every
/// component test compiles. Each of `modules` is one more module of
/// the program's own, a file under `src/<name>/`.
export fn provided(main: string, provider: string, modules: List<Module> = []) -> Judged {
    held_at(provided_files(main, provider, modules), "/w").judged_at("/w/src/main.av")
}

/// The package `provided` judges, held: for an ask of its files that judges nothing.
export fn provided_held(main: string, provider: string, modules: List<Module> = []) -> Held {
    held_at(provided_files(main, provider, modules), "/w")
}

/// The files `provided` holds.
export fn provided_files(main: string, provider: string, modules: List<Module>) -> Map<
    string,
    string,
> {
    mut files = vendored_meta(
        {
            "/w/avra.toml": "[package]\nname = \"app\"\nversion = \"0.1.0\"\n\n[dependencies]\n\"@std/meta\" = { path = \"vendor/meta\" }\n\"@x/c\" = { path = \"vendor/c\" }\n",
            "/w/src/main.av": main,
            "/w/vendor/c/avra.toml": "[package]\nname = \"@x/c\"\nversion = \"0.1.0\"\n\n[dependencies]\n\"@std/meta\" = { path = \"../meta\" }\n",
            "/w/vendor/c/src/c.av": "use @std.meta.{Code}\n" + provider,
        },
    )
    for m in modules { files.set(m.path(), m.text) }
    files
}

// ── The prelude, carried in memory ───────────────────────────────────

const prelude_real: string = embed("@std/prelude/src/prelude.av")
