== item_decl_shapes.av
fn seats_typeless(engine: QueryEngine, file: SourceFileAddress, at: int) -> List<Found> {
    if !item_held(engine, file, at) { return [] }
    let item = read_item(engine, file, at)
    let fns = item
        .stmts
        .concat([f for s in item.stmts for f in item.store.impl_parts(s)?.fns ?? []])
    [Found { at: item.store.stmt_span(f), args: [p.name.of] } for f in fns for p in item.store.fn_parts(f)?.params ?? [] if p.ty == null && p.seated()]
}
== item_unresolved.av
fn receivers_unread(engine: QueryEngine, file: SourceFileAddress, at: int) -> List<Found> {
    let unread = [u for u in item_refusals(engine, file, at).unread if u.read is .Receiver]
    if unread.is_empty() { return [] }
    let item = read_item(engine, file, at)
    [Found { at: span_of(u.at), args: [receiverless_word(item, u.at)] } for u in unread]
}
== item_assignments.av
fn unslotted(engine: QueryEngine, file: SourceFileAddress, at: int) -> List<Found> {
    if !item_held(engine, file, at) { return [] }
    let item = read_item(engine, file, at)
    if !item.store.refusals().is_empty() { return [] }
    flatten(
        [slots_missed(b).concat(types_written(engine, file, b)) for b in bodies_of(engine, file, at, item)],
    )
}
